```openscad
// Cuvette stand for 5 standard 1 cm spectrophotometer cuvettes
// Units: mm. Print orientation: base on z = 0, pockets open upward.

// ---- Block ----
block_x = 102;      // block length along X
block_y = 30;       // block width along Y
block_z = 25;       // block height

// ---- Pockets ----
n_pockets      = 5;     // number of cuvette pockets
pocket_w       = 13.2;  // pocket size in X and Y (square)
pocket_depth   = 20;    // pocket depth from top face
pocket_pitch   = 18.2;  // centre-to-centre spacing along X
floor_thick    = block_z - pocket_depth; // 5 mm floor under pockets

// ---- Modelling ----
eps = 0.5;          // overshoot of cutters past the top face
$fn = 64;

// X position of first pocket centre so the row is centred on the block
row_start_x = -(n_pockets - 1) * pocket_pitch / 2;

difference() {
    // main block, centred in X/Y, sitting on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_z]);

    // row of square pockets opened from the top
    for (i = [0 : n_pockets - 1])
        translate([row_start_x + i * pocket_pitch - pocket_w / 2,
                   -pocket_w / 2,
                   floor_thick])
            cube([pocket_w, pocket_w, pocket_depth + eps]);
}
```

