// ---- Pockets ----
pocket_count = 4;    // number of cuvette pockets
pocket_w     = 13;   // pocket size in X and Y (square)
pocket_depth = 22;   // pocket depth from top face
pocket_pitch = 19;   // centre-to-centre spacing along X
floor_t      = block_h - pocket_depth; // floor thickness under pockets (3 mm)

// ---- Misc ----
eps = 0.5;           // overshoot for clean boolean cuts
$fn = 64;

difference() {
    // Main block, centred in X/Y, sitting on z = 0
    translate([-block_x/2, -block_y/2, 0])
        cube([block_x, block_y, block_h]);

    // Row of square pockets, centred on the block
    for (i = [0 : pocket_count - 1]) {
        px = (i - (pocket_count - 1)/2) * pocket_pitch;
        translate([px - pocket_w/2, -pocket_w/2, floor_t])
            cube([pocket_w, pocket_w, pocket_depth + eps]);
    }
}
