```openscad
// Horizontal pipette rest
// Print orientation: base plate on the bed, uprights building up in +Z

$fn = 96;

// ---- Base plate ----
base_len   = 120;   // plate length along X
base_wid   = 30;    // plate width along Y
base_thk   = 5;     // plate thickness along Z

// ---- Uprights ----
up_thk     = 12;    // upright thickness along X
up_h       = 40;    // upright height (top at z = 40)

// ---- Cradle notch ----
notch_r    = 7;     // semicircular notch radius
notch_z    = up_h;  // notch centre height (on top edge)
notch_y    = 0;     // notch centre Y position

eps        = 0.5;   // overcut for clean differences

difference() {
    union() {
        // Base plate, centred on origin in X/Y
        translate([-base_len/2, -base_wid/2, 0])
            cube([base_len, base_wid, base_thk]);

        // Uprights flush with each end of the plate
        for (s = [-1, 1])
            translate([s > 0 ? base_len/2 - up_thk : -base_len/2, -base_wid/2, 0])
                cube([up_thk, base_wid, up_h]);
    }

    // Semicircular cradle notches through each upright along X
    for (s = [-1, 1])
        translate([s * (base_len/2 - up_thk/2), notch_y, notch_z])
            rotate([0, 90, 0])
                cylinder(r = notch_r, h = up_thk + 2*eps, center = true);
}
```

