// Horizontal pipette rest
// Units: mm. Print orientation: base plate on the bed (z = 0), building up +Z.

// ---------- Parameters ----------
base_len      = 180;   // base plate length (X)
base_wid      = 35;    // base plate width (Y)
base_thk      = 4;     // base plate thickness (Z)

upright_thk   = 10;    // upright block thickness (X)
upright_h     = 35;    // upright top height (Z), measured from bed

cradle_r      = 7;     // semicircular cradle notch radius
cradle_z      = upright_h; // notch centre height (on top edge)
cradle_y      = 0;     // notch centre Y position

eps           = 0.5;   // cutter overshoot past cut faces
$fn           = 96;    // curve resolution

// ---------- Model ----------
difference() {
    union() {
        // Base plate
        translate([-base_len/2, -base_wid/2, 0])
            cube([base_len, base_wid, base_thk]);

        // Uprights, flush with each end of the plate
        for (sx = [-1, 1])
            translate([sx > 0 ? base_len/2 - upright_thk : -base_len/2,
                       -base_wid/2, 0])
                cube([upright_thk, base_wid, upright_h]);
    }

    // Cradle notches, running through each upright along X
    for (sx = [-1, 1])
        translate([sx * (base_len/2 - upright_thk/2) - (upright_thk/2 + eps),
                   cradle_y, cradle_z])
            rotate([0, 90, 0])
                cylinder(r = cradle_r, h = upright_thk + 2*eps);
}
