```openscad
// Hex key organiser block
// Print orientation: block standing on z = 0, pockets open to the top (+Z)

// ---------------- Block dimensions ----------------
block_len    = 82;    // block length along X (mm)
block_wid    = 16;    // block width along Y (mm)
block_hgt    = 25;    // block height along Z (mm)

// ---------------- Pocket parameters ----------------
pocket_depth = 15;    // depth of each hex pocket from the top face (mm)
pocket_pitch = 12;    // centre-to-centre spacing of pockets along X (mm)
pocket_flats = [2.4, 2.9, 3.4, 4.4, 5.4, 6.4]; // across-flats sizes, -X to +X (mm)
pocket_count = len(pocket_flats);             // number of pockets
overcut      = 0.5;   // extension of cutters past the top face (mm)

// Hexagon circumradius from across-flats dimension
function hex_r(f) = f / sqrt(3);

difference() {
    // Main block, centred in X and Y, sitting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_hgt]);

    // Hexagonal pockets along y = 0, centred on the block
    // cylinder with $fn = 6 places vertices on the X axis,
    // so two flats are parallel to the X axis
    for (i = [0 : pocket_count - 1]) {
        x = (i - (pocket_count - 1) / 2) * pocket_pitch;
        translate([x, 0, block_hgt - pocket_depth])
            cylinder(r = hex_r(pocket_flats[i]),
                     h = pocket_depth + overcut,
                     $fn = 6);
    }
}
