// Glassware drying board: base plate with 4x4 grid of vertical pegs
$fn = 64;

// Base plate
plate_x = 135;      // plate length along X
plate_y = 135;      // plate length along Y
plate_t = 6;        // plate thickness (z = 0 to 6)

