peg_h = peg_top - plate_t; // peg height above plate (30)
peg_nx = 4;         // pegs along X
peg_ny = 4;         // pegs along Y
peg_pitch = 35;     // centre-to-centre spacing
overlap = 0.5;      // peg sinks into plate for a clean union

union() {
    // Base plate centred on origin
    translate([-plate_x/2, -plate_y/2, 0])
        cube([plate_x, plate_y, plate_t]);

    // Peg grid centred on plate
    for (i = [0:peg_nx-1])
        for (j = [0:peg_ny-1])
            translate([(i - (peg_nx-1)/2) * peg_pitch,
                       (j - (peg_ny-1)/2) * peg_pitch,
                       plate_t - overlap])
                cylinder(d = peg_d, h = peg_h + overlap);
}
