plate_t      = 6;     // base plate thickness (mm), z = 0 to 6

peg_d        = 8;     // peg diameter (mm)
peg_top_z    = 56;    // height of peg tops above the bed (mm)
peg_h        = peg_top_z - plate_t;  // peg height above the plate top (50 mm)

peg_nx       = 3;     // number of pegs along X
peg_ny       = 4;     // number of pegs along Y
peg_pitch    = 40;    // centre-to-centre peg spacing in X and Y (mm)

overlap      = 0.5;   // pegs sink this far into the plate so the union fuses cleanly (mm)

$fn = 64;             // resolution for round features

// ---------- Derived ----------
grid_x0 = -(peg_nx - 1) * peg_pitch / 2;   // first peg X position (centres the grid)
grid_y0 = -(peg_ny - 1) * peg_pitch / 2;   // first peg Y position (centres the grid)

// ---------- Model ----------
union() {
    // Base plate, centred on the origin in X and Y
    translate([-plate_x / 2, -plate_y / 2, 0])
        cube([plate_x, plate_y, plate_t]);

    // Peg grid
    for (i = [0 : peg_nx - 1])
        for (j = [0 : peg_ny - 1])
            translate([grid_x0 + i * peg_pitch,
                       grid_y0 + j * peg_pitch,
                       plate_t - overlap])
                cylinder(d = peg_d, h = peg_h + overlap);
}
