// Adjustable shim plate with two rounded-end bolt slots
// Print orientation: flat on bed, z = 0 at bottom face

// ---------- Plate ----------
plate_len   = 50;    // plate length along X (mm)
plate_wid   = 30;    // plate width along Y (mm)
plate_thk   = 4;     // plate thickness along Z (mm)

// ---------- Slots ----------
slot_w      = 4.5;   // slot width (mm) = end-radius * 2
slot_len    = 12;    // slot overall length, end to end (mm)
slot_xs     = [-14, 14]; // slot centre X positions (mm)
slot_y      = 0;     // slot centre Y position (mm)

// ---------- Misc ----------
eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 96;    // curve resolution

slot_r      = slot_w / 2;              // end radius
slot_cc     = slot_len - slot_w;       // centre-to-centre of end arcs

module slot_cutter() {
    // Stadium-shaped through-cutter, centred on origin, running along X
    translate([0, 0, -eps])
        hull() {
            for (sx = [-slot_cc / 2, slot_cc / 2])
                translate([sx, 0, 0])
                    cylinder(r = slot_r, h = plate_thk + 2 * eps, $fn = 96);
        }
}

difference() {
    // Plate body
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Bolt slots
    for (x = slot_xs)
        translate([x, slot_y, 0])
            slot_cutter();
}
