// Microplate riser
// Print orientation: legs down on the bed (z = 0), top plate at z = 25..30

// ---------------- Dimensions (mm) ----------------
plate_x      = 130;   // top plate length (X)
plate_y      = 100;   // top plate width (Y)
plate_t      = 5;     // top plate thickness
top_z        = 30;    // height of top face of plate
leg_size     = 10;    // square leg side length
window_x     = 90;    // central window length (X)
window_y     = 60;    // central window width (Y)
eps          = 0.5;   // cutter overshoot past faces
overlap      = 0.01;  // leg/plate overlap for a clean union

// Derived
plate_bot_z  = top_z - plate_t;   // underside of plate (z = 25)
leg_h        = plate_bot_z;       // legs run from z = 0 to underside

$fn = 64;

// ---------------- Model ----------------
union() {
    // Top plate with central window
    difference() {
        translate([-plate_x/2, -plate_y/2, plate_bot_z])
            cube([plate_x, plate_y, plate_t]);
        translate([-window_x/2, -window_y/2, plate_bot_z - eps])
            cube([window_x, window_y, plate_t + 2*eps]);
    }

    // Four corner legs, flush with plate outer edges
    for (sx = [-1, 1], sy = [-1, 1]) {
        translate([sx > 0 ? plate_x/2 - leg_size : -plate_x/2,
                   sy > 0 ? plate_y/2 - leg_size : -plate_y/2,
                   0])
            cube([leg_size, leg_size, leg_h + overlap]);
    }
}
