```openscad
// Magnet carrier disc for a rotating sample mixer
// Print orientation: flat on the bed, pockets opening upward (+Z)
//
// NOTE: With 6 pockets of 10.2 mm diameter on a 19.8 mm pitch circle,
// adjacent pocket centres are only 2*9.9*sin(30) = 9.9 mm apart, which is
// less than the 10.2 mm pocket diameter. Neighbouring pockets will therefore
// merge (about 0.3 mm overlap), and 10 mm magnets would touch or collide.
// The model follows the given dimensions exactly. Check the pitch circle
// (>= ~21 mm would leave a 0.3 mm wall) if separate pockets are needed.

$fn = 96;                      // facet count for curved surfaces

// ---------- Disc body ----------
disc_d        = 40;            // carrier disc outer diameter
disc_h        = 8;             // carrier disc height

// ---------- Magnet pockets ----------
pocket_count  = 6;             // number of magnet pockets
pocket_d      = 10.2;          // pocket diameter (magnet + clearance)
pocket_depth  = 4;             // pocket depth from top face
pitch_d       = 19.8;          // pitch-circle diameter of pocket centres
first_angle   = 0;             // first pocket on +X axis (degrees)

// ---------- Shaft hole ----------
shaft_d       = 6;             // motor shaft through-hole diameter

// ---------- Helpers ----------
eps           = 0.5;           // overshoot for clean boolean cuts

difference() {
    // Main disc, centred on origin in XY, sitting on z = 0
    cylinder(d = disc_d, h = disc_h);

    // Magnet pockets cut into top face
    for (i = [0 : pocket_count - 1]) {
        a = first_angle + i * 360 / pocket_count;
        translate([pitch_d / 2 * cos(a),
                   pitch_d / 2 * sin(a),
                   disc_h - pocket_depth])
            cylinder(d = pocket_d, h = pocket_depth + eps);
    }

    // Central shaft through-hole
    translate([0, 0, -eps])
        cylinder(d = shaft_d, h = disc_h + 2 * eps);
}
```

