// Wall mounting strip with two countersunk screw holes
// Print orientation: flat on the bed, countersinks facing up (+Z)

// ---------------- Parameters ----------------
bar_length   = 80;    // bar length along X (mm)
bar_width    = 20;    // bar width along Y (mm)
bar_thick    = 5;     // bar thickness along Z (mm)

hole_count   = 2;     // number of screw holes
hole_pitch   = 50;    // centre-to-centre hole spacing along X (mm)
hole_d       = 5.5;   // through-hole diameter (mm)
csk_d        = 11;    // countersink diameter at top surface (mm)
csk_angle    = 90;    // countersink included angle (degrees)

eps          = 0.5;   // overshoot of cutters past faces (mm)
$fn          = 96;    // circle resolution

// Derived values
csk_depth    = (csk_d - hole_d) / 2 / tan(csk_angle / 2);  // = 2.75 mm for 90 deg
csk_top_d    = csk_d + 2 * eps * tan(csk_angle / 2);       // cone diameter at overshoot height

// ---------------- Model ----------------
difference() {
    // Flat bar, centred in X/Y, resting on z = 0
    translate([-bar_length / 2, -bar_width / 2, 0])
        cube([bar_length, bar_width, bar_thick]);

    // Screw holes, centred on the bar along X at y = 0
    for (i = [0 : hole_count - 1]) {
        x = -hole_pitch * (hole_count - 1) / 2 + i * hole_pitch;
        translate([x, 0, 0]) {
            // Through-hole
            translate([0, 0, -eps])
                cylinder(h = bar_thick + 2 * eps, d = hole_d);
            // 90-degree countersink on top face
            translate([0, 0, bar_thick - csk_depth])
                cylinder(h = csk_depth + eps, d1 = hole_d, d2 = csk_top_d);
        }
    }
}
