eps       = 0.5;                                       // cutter overshoot
first_x   = -(hole_count - 1) * hole_pitch / 2;        // x of first hole

difference() {
    // Bar body, centred in X/Y, resting on z = 0
    translate([-bar_length / 2, -bar_width / 2, 0])
        cube([bar_length, bar_width, bar_thickness]);

    for (i = [0 : hole_count - 1]) {
        translate([first_x + i * hole_pitch, 0, 0]) {
            // Through-hole
            translate([0, 0, -eps])
                cylinder(d = hole_d, h = bar_thickness + 2 * eps);

            // 90-degree countersink, extended eps above top face
            // (diameter grows by 2*eps*tan(45) = 2*eps over the extension)
            translate([0, 0, bar_thickness - csk_depth])
                cylinder(d1 = hole_d,
                         d2 = csk_d + 2 * eps * tan(csk_angle / 2),
                         h  = csk_depth + eps);
        }
    }
}
