notch_w     = 4;   // notch width along X (mm)
notch_d     = 12;  // notch depth into plate along -Y (mm)
notch_pitch = 10;  // centre-to-centre spacing along X (mm)

// ---------- Misc ----------
eps = 0.5;   // overcut so cutters pass beyond faces
$fn = 64;

// X position of first notch so the row is centred on the origin
notch_x0 = -(notch_n - 1) * notch_pitch / 2;

difference() {
    // Base plate, centred in X and Y, resting on z = 0
    translate([-plate_l / 2, -plate_w / 2, 0])
        cube([plate_l, plate_w, plate_t]);

    // Notches cut from the +Y edge, through the full thickness
    for (i = [0 : notch_n - 1])
        translate([notch_x0 + i * notch_pitch - notch_w / 2,
                   plate_w / 2 - notch_d,
                   -eps])
            cube([notch_w, notch_d + eps, plate_t + 2 * eps]);
}
